import re
ID = re.compile(r'^[^§\n]{0,3}§\s*(?P<id>[0-9]+[A-Z]?-[0-9]+[A-Z]?-[0-9]+(?:\.[0-9]+)?[A-Za-z]?)\.?\s*(?P<heading>.*)$')
def sections():
    kind, sm = fetch('https://code.wvlegislature.gov/sitemap.xml')
    # the section pages themselves: an article page arrives without its sections' text (the browser loads it later), which
    # is how 23,530 sections landed as a bare heading (2026-10-03)
    urls = list(dict.fromkeys(re.findall(r'<loc>\s*(https://code\.wvlegislature\.gov/[0-9A-Z]+-[0-9A-Z]+-[0-9A-Z.]+/)\s*</loc>', sm, re.I)))
    log('section pages: ' + str(len(urls)))
    for url in urls:
        want = url.rstrip('/').rsplit('/', 1)[1]
        try:
            kind, body = fetch(url)
        except Exception as e:
            log('section failed ' + url + ' ' + repr(e)); continue
        # the section's own box: its heading and its paragraphs. A box can open with its part's heading ("Part I. General",
        # then "§5B-2L-1. Short title."), and the neighbours' boxes on the page carry the heading alone: take the longest
        # box whose section line is near its top (487 sections had landed as their neighbour's bare heading, 2026-10-06)
        best = None
        for block in block_texts(body, cls='sectiontext'):
            lines = block.split('\n')
            for i, line in enumerate(lines[:4]):
                m = ID.match(line)
                if m and m.group('id').lower() == want.lower():
                    text = '\n'.join(lines[i:])
                    if not best or len(text) > len(best[1]):
                        best = (m, text)
                    break
        if best:
            yield {'id': best[0].group('id'), 'heading': best[0].group('heading').strip(), 'text': best[1], 'url': url}
